import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return (a * b) // gcd(a, b)

def calculate_a_n_mod_p(n, p):
    # a_n = 6^n + 2^n + 3^n - 1
    return (pow(6, n, p) + pow(2, n, p) + pow(3, n, p) - 1) % p

def check_prime_divides_a_n(p):
    if p == 2:
        # a_n = 6^n + 2^n + 3^n - 1
        # For n>=1, a_n = 0 + 0 + 1 - 1 = 0 (mod 2)
        return True
    if p == 3:
        # a_n = 0 + (-1)^n + 0 - 1 (mod 3)
        # Solvable for even n
        return True

    # For other primes p, the sequence a_n mod p is periodic.
    # The maximum period length L divides lcm(ord_p(6), ord_p(2), ord_p(3)), 
    # which is at most p-1 (by Fermat's Little Theorem).

    # We check n from 1 up to p. If a solution exists, it must occur within this range.
    for n in range(1, p + 1):
        if calculate_a_n_mod_p(n, p) == 0:
            return True
    return False

primes = [p for p in range(2, 101) if all(p % i != 0 for i in range(2, int(math.sqrt(p)) + 1))]

results = {}
for p in primes:
    results[p] = check_prime_divides_a_n(p)

# Check a few more larger primes manually or by extending the check if needed
large_primes = [101, 103, 107, 109]
for p in large_primes:
    results[p] = check_prime_divides_a_n(p)

# Count how many primes were covered
covered_primes = sum(1 for res in results.values() if res)
total_primes = len(primes)
print(f"Tested {len(results)} primes up to 109.")
print(f"Number of primes successfully covered (i.e., a solution exists): {covered_primes}")
